import assert from 'node:assert/strict';
import { readFileSync, mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import test from 'node:test';
import { BLOCK_OVERHEAD_BYTES, encodeBatch } from './codec.mjs';

// Generated by codec-oracle.rs against src/codec.rs, not by the JS port.
const fixtures = JSON.parse(readFileSync(new URL('./codec-fixtures.json', import.meta.url)));
function pointsFromRaw(raw) {
  return Array.from({ length: raw.length / 16 }, (_, i) => ({
    ts: Number(raw.readBigInt64LE(i * 16)), value: raw.readDoubleLE(i * 16 + 8),
  }));
}

for (const fixture of fixtures) {
  test(`matches Rust byte-for-byte: ${fixture.name}`, () => {
    const original = Buffer.from(fixture.raw, 'hex');
    const golden = Buffer.from(fixture.gorilla, 'hex');
    const points = pointsFromRaw(original);
    const result = encodeBatch(points);
    const codec = golden.length < original.length ? 'gorilla' : 'raw';
    const payload = codec === 'gorilla' ? golden : original;
    assert.equal(result.codec, codec);
    assert.deepEqual(result.raw, original); // includes exact float bits and -0
    assert.deepEqual(result.compressed.subarray(54, -4), payload);
    assert.equal(result.raw.length, points.length * 16);
    assert.equal(result.compressed.length, BLOCK_OVERHEAD_BYTES + payload.length);
    assert.equal(result.compressed[0], codec === 'gorilla' ? 1 : 0);
    assert.equal(result.compressed.readUInt32LE(2), points.length);
    assert.equal(result.compressed.readUInt32LE(46), payload.length);
    assert.equal(result.compressed.readBigInt64LE(6), BigInt(Math.min(...points.map(p => p.ts))));
    assert.equal(result.compressed.readBigInt64LE(14), BigInt(Math.max(...points.map(p => p.ts))));
    assert.equal(result.compressed.readDoubleLE(22), Math.min(...points.map(p => p.value)));
    assert.equal(result.compressed.readDoubleLE(30), Math.max(...points.map(p => p.value)));
    const sum = points.reduce((acc, point) => acc + point.value, 0);
    assert.equal(result.compressed[1], Number(Number.isFinite(sum)));
    assert.ok(Object.is(result.compressed.readDoubleLE(38), Number.isFinite(sum) ? sum : NaN));
  });
}

test('honestly includes overhead even when the persisted block is larger', () => {
  const result = encodeBatch([{ ts: 1, value: 1 }]);
  assert.equal(result.codec, 'raw');
  assert.equal(result.raw.length, 16);
  assert.equal(result.compressed.length, 74);
});

test('rejects invalid batches instead of rounding or dropping data', () => {
  for (const points of [null, [], [{ ts: 0.5, value: 1 }], [{ ts: 2 ** 53, value: 1 }],
    [{ ts: 0, value: NaN }], [{ ts: 0, value: Infinity }], [{ ts: 0, value: '1' }], [null]]) {
    assert.throws(() => encodeBatch(points));
  }
});

test('Rust opens and queries every emitted v3 block losslessly', {
  skip: !process.env.SHRUNK_RUST_ORACLE && 'set SHRUNK_RUST_ORACLE to the compiled development oracle',
}, () => {
  const directory = mkdtempSync(join(tmpdir(), 'shrunk-codec-'));
  try {
    for (const fixture of fixtures) {
      const result = encodeBatch(pointsFromRaw(Buffer.from(fixture.raw, 'hex')));
      const rawPath = join(directory, 'raw');
      const blockPath = join(directory, 'block');
      writeFileSync(rawPath, result.raw);
      writeFileSync(blockPath, result.compressed);
      const check = spawnSync(process.env.SHRUNK_RUST_ORACLE, [rawPath, blockPath], { encoding: 'utf8' });
      assert.equal(check.status, 0, `${fixture.name}: ${check.stderr || check.error || ''}`);
    }
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});
